import { readFile, writeFile } from "node:fs/promises";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { rolldown } from "rolldown";

const root = fileURLToPath(new URL("..", import.meta.url));
const sourcePath = `${root}/src/runtime/web-runtime-kernel.ts`;
const generatedPath = `${root}/src/runtime/web-runtime.generated.ts`;
const header =
  "// @ts-nocheck -- generated JavaScript is verified against its typed kernel.\n" +
  "/* oxlint-disable no-useless-escape -- Rolldown protects closing script tags. */\n" +
  "// GENERATED by Rolldown from web-runtime-kernel.ts. Run pnpm runtime:generate.\n";
const bundle = await rolldown({ input: sourcePath, external: ["@plotpoint/protocol"] });
const generated = await bundle.generate({ format: "es" });
await bundle.close();
const chunk = generated.output.find((item) => item.type === "chunk");
if (chunk === undefined) throw new Error("generated-web-runtime-chunk-missing");
const unformatted = `${header}${chunk.code}`;
const formatted = spawnSync(
  `${root}/../../node_modules/.bin/oxfmt`,
  ["--stdin-filepath", generatedPath],
  { input: unformatted, encoding: "utf8" },
);
if (formatted.status !== 0) throw new Error("generated-web-runtime-format-failed");
const expected = formatted.stdout;

if (process.argv.includes("--check")) {
  const actual = await readFile(generatedPath, "utf8").catch(() => "");
  if (actual !== expected) {
    throw new Error("generated-web-runtime-stale");
  }
} else {
  await writeFile(generatedPath, expected);
}
